package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamAnuradhapuraMuralBank2 {
    private const val T = "අනුරාධපුර යුගයේ බිතුසිතුවම් කලාව"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("අනුරාධපුර යුගයේ අවසන් භාගයට අයත් බෞද්ධ බිතුසිතුවම් හමුවන මහනුවර ආසන්නයේ පිහිටි ස්ථානය කුමක්ද?", "හිඳගල රජමහා විහාරය", "දෙගල්දොරුව විහාරය", "මැදවල ටැම්පිට විහාරය", "සූරියගොඩ විහාරය", "පේරාදෙණිය ආසන්නයේ හිඳගල ගල් ලෙනෙහි ක්‍රි.ව. 7 වන සියවසට පමණ අයත් අනුරාධපුර යුගයේ සිතුවම් හමුවේ."),
        q("හිඳගල විහාරයේ පැරණි බිතුසිතුවම් තුළ නිරූපණය කර ඇති ප්‍රධාන බෞද්ධ දර්ශන මොනවාද?", "සක්‍ර දේවේන්ද්‍රයාගේ පැමිණීම හා අනුරූ බුදු සිරිතේ අවස්ථා", "වෙස්සන්තර ජාතකයේ මහනුවර පෙළ", "කුවේණි අස්න හා විජයාගමනය", "පොළොන්නරු යුගයේ සස ජාතකය", "හිඳගල ලෙනෙහි ඉන්ද්‍රසාල ගුහා දර්ශනය හා සත්සතිය හා බැඳුණු සිතුවම් දැකිය හැකි බව විද්වත්හු පවසති."),
        q("හිඳගල බිතුසිතුවම් කලා ඉතිහාසයේ සුවිශේෂී ස්ථානයක් හිමිකර ගන්නේ කුමන කරුණක් නිසාද?", "ලංකාවේ දැනට ඉතිරිව ඇති පැරණිතම බෞද්ධ බිතුසිතුවම් අතරින් එකක් වීම", "ලංකාවේ ප්‍රථම තෙල් සායම් සිතුවම් වීම", "සම්පූර්ණ වීදුරු මොසැයික්වලින් තැනීම", "පෘතුගීසි පාලන සමයේ ඇඳ තිබීම", "සීගිරිය ලෞකික සිතුවම් වුවද හිඳගල පැරණිතම බෞද්ධ ආගමික ලෙන් සිතුවම් නියෝජනය කරයි."),
        q("හිඳගල බිතුසිතුවම්වල බුදුන් වහන්සේගේ සිරුර හා මුහුණු ඇඳීමේදී දක්නට ලැබෙන විශේෂ ලක්ෂණය කුමක්ද?", "සීගිරි ශෛලියට සමාන නම්‍යශීලී රේඛා හා මෘදු සෙවණැලි භාවිතය", "මහනුවර යුගයේ පැතලි රතු පසුබිම", "ඝනිකවාදී ජ්‍යාමිතික කැබලි කිරීම", "අඳුරු බැරොක් කළු පසුබිම", "ක්‍රි.ව. 6–7 සියවස්වල සම්භාව්‍ය අනුරාධපුර රේඛා ශෛලිය හිඳගල සිතුවම්වලද පැහැදිලිව පෙනේ."),
        q("මිහින්තලේ කණ්ඨක චේතිය ආශ්‍රිතව හා දාගැබ් ධාතු ගර්භවලින් හමු වූ බිතුසිතුවම්වල වයස කුමක්ද?", "ක්‍රි.ව. 8 සිට 10 වන සියවස් අතර කාලය", "ක්‍රි.ව. 19 වන සියවස", "ක්‍රි.ව. 17 වන සියවස", "ක්‍රි.පූ. 10 වන සියවස", "මිහින්තලේ හා මහියංගණ ධාතු ගර්භවලින් පසු අනුරාධපුර යුගයට අයත් බිතුසිතුවම් සොයාගෙන ඇත."),
        q("මිහින්තලේ ධාතු ගර්භ සිතුවම්වල ප්‍රධාන වශයෙන් නිරූපණය කර තිබුණේ කුමන පිරිසක්ද?", "වලාකුළු අතරින් පාවෙන දේවතාවුන් හා මල් ඉසින දිව්‍ය රූප", "සටන් වදින පෘතුගීසි සොල්දාදුවන්", "කැලණි ගඟේ පාරු පදවන්නන්", "මහනුවර නිලමේවරුන් හා රජවරුන්", "නෙළුම් මල් ගෙන බුදුන් හා ධාතූන් වන්දනා කරන දේව රූප ධාතු ගර්භ බිත්තිවල ඇඳ තිබුණි."),
        q("මහියංගණ දාගැබේ ධාතු ගර්භය ප්‍රතිසංස්කරණය කිරීමේදී හමු වූ 11 වන සියවස පමණ යුගයේ සිතුවමේ ප්‍රධාන තේමාව කුමක්ද?", "බෝධි මූලයේදී මාර පරාජය හා දේවාරාධනාව", "සිංහබාහු සහ සිංහසීවලී පුවත", "උම්මග්ග ජාතකයේ මහෞෂධ පඬිතුමා", "නළ දමයන්ති කතා පුවත", "අනුරාධපුර අවසානය හා පොළොන්නරු ආරම්භය අතර බිහි වූ මෙහි බ්‍රහ්ම, විෂ්ණු හා දේව රූප දක්නට ලැබිණි."),
        q("අම්පාර දිස්ත්‍රික්කයේ පිහිටි 'ගෝනගොල්ල' විහාරයේ ගල් ලෙනෙහි දැකිය හැකි පැරණි බිතුසිතුවම කුමක්ද?", "බෝධිසත්ව රුවක් හා නමස්කාර කරන කාන්තා රුවක්", "ගජසිංහ සහ භේරුණ්ඩ පක්ෂියා", "දිය කෙළියේ යෙදෙන හංස පිරිස", "වෙස්සන්තර රජුගේ දන්සැල", "ගෝනගොල්ල පුංචි සීගිරිය ලෙසද හැඳින්වෙන මෙම ලෙනෙහි සීගිරි සම්ප්‍රදායට සමාන බිතුසිතුවමක් වේ."),
        q("ගෝනගොල්ල බිතුසිතුවම් 'පුංචි සීගිරිය' ලෙස හඳුන්වනු ලබන්නේ ඇයි?", "සීගිරි සිතුවම්වල රේඛා හා වර්ණ ශෛලියට බෙහෙවින් සමාන වීම නිසා", "ගෝනගොල්ල පර්වතයේ සිංහ පාදයක් ඇති නිසා", "කාශ්‍යප රජු එහි මාලිගාවක් හැදූ නිසා", "එහි කාන්තා රූප පන්සියයක් ඇති නිසා", "රේඛා ලාලිත්‍යය, ඔටුන්න හා කහ රතු වර්ණ භාවිතය අනුරාධපුර සම්භාව්‍ය සීගිරි සම්ප්‍රදාය සිහිගන්වයි."),
        q("අනුරාධපුරයේ 'වෙස්සගිරිය' ගල් ලෙන්වල පැරණි බිතුසිතුවම්වලින් ඉතිරිව ඇති ලක්ෂණ මොනවාද?", "සීගිරි ශෛලියට සමාන රතු, කහ හා කොළ පැහැති බදාම සිතුවම් කොටස්", "නූතන තෙල් සායම් බුදු රූප", "මහනුවර යුගයේ ජාතක කතා තීරු පෙළ", "වීදුරු කැටයම් මණ්ඩප සිතුවම්", "වෙස්සගිරි ලෙන් සිවිලිමේ හා බිත්තිවල අනුරාධපුර යුගයේ සිතුවම් ශේෂ සංරක්ෂණය වී ඇත."),
        q("අනුරාධපුර රුවන්වැලි මහා සෑයේ පේසා වළලු හා වාහල්කඩ ආශ්‍රිතව දක්නට ලැබුණු සිතුවම් කවරේද?", "මල්කම්, ලියකම් සහ නෙළුම් මල් සැරසිලි රටා", "මුහුදු යාත්‍රා හා නාවික සිතියම්", "පෘතුගීසි ලාංඡන හා කුරුස", "චීන අධිරාජ්‍යයන්ගේ රූප", "දාගැබ් හා ගොඩනැගිලි බිත්ති අලංකාර කිරීමට රතු හා කහ පැහැයෙන් මල් ලියවැල් ඇඳ තිබුණි."),
        q("මහාවංශයේ සඳහන් වන පරිදි දුටුගැමුණු රජතුමා රුවන්වැලිසෑයේ ධාතු ගර්භය තුළ චිත්‍ර හා රූප කරවූයේ කුමන ද්‍රව්‍ය හා තේමා යොදාගෙනද?", "සත්සතිය හා ජාතක කතා රන් හා සිතුවම් මගින්", "වීදුරු හා ප්ලාස්ටික් චිත්‍ර මගින්", "ලන්දේසි පිඟන් කැබලි මගින්", "කළුගල් කෙටුම් මගින් පමණක්", "ලෝහ ප්‍රතිමා මෙන්ම ධාතු ගර්භ බිත්තිවල ජාතක කතා හා බුදු සිරිත සිතුවමින් නිර්මාණය කළ බව මහාවංශය කියයි."),
        q("දඹුල්ල රජමහා විහාරයේ මුල් කාලීන ලෙන් බදාම ස්ථර පරීක්ෂාවේදී පැරණිතම සිතුවම් කුමන යුගයකට අයත් බව පෙනේද?", "අනුරාධපුර හා පොළොන්නරු යුග අවධිය", "බ්‍රිතාන්‍ය පාලනයෙන් පසු යුගය", "පෘතුගීසි යුගය පමණක්", "20 වන සියවසේ නූතන යුගය", "දඹුල්ලේ අද පෙනෙන සිතුවම් මහනුවර යුගයේ වුවද ඒ යටින් පැරණි අනුරාධපුර බදාම ස්තර හමු වී ඇත."),
        q("කරඹගල ලෙන් විහාරයේ (හම්බන්තොට දිස්ත්‍රික්කයේ) හමුවන පැරණි සිතුවම් ශේෂ අයත් වන්නේ කුමන සම්ප්‍රදායටද?", "පසු අනුරාධපුර සම්භාව්‍ය බිතුසිතුවම් සම්ප්‍රදාය", "මහනුවර ගැමි රූකඩ සම්ප්‍රදාය", "බටහිර පුනරුද තෙල් සායම් සම්ප්‍රදාය", "ජපන් සුමි-ඊ තීන්ත සම්ප්‍රදාය", "දකුණු ලංකාවේ කරඹගල ලෙනෙහි අනුරාධපුර යුගයේ සම්භාව්‍ය රේඛා හා වර්ණ ලක්ෂණ ඇති සිතුවම් ශේෂ හමුවේ."),
        q("සීගිරිය හා හිඳගල වැනි අනුරාධපුර යුගයේ සිතුවම්වල 'රූප රචනා රීතිය' (Canon of Art) බොහෝ විට අනුගමනය කර ඇත්තේ කුමන ඉන්දීය න්‍යායද?", "ෂඩංග හෙවත් චිත්‍ර කලාවේ අංග හය", "බටහිර ඝනිකවාදී රීතිය", "ඊජිප්තු ඉදිරිපස-පැතිකඩ රීතිය", "ජපන් ඔරිගාමි ජ්‍යාමිතික රීතිය", "රූපභේද, ප්‍රමාණ, භාව, ලාවණ්‍ය, සාදෘශ්‍ය හා වර්ණිකභංග යන ෂඩංග නියමයන් මෙහි විද්‍යමාන වේ."),
        q("අනුරාධපුර යුගයේ චිත්‍ර කලාවේදී 'ලාවණ්‍ය යෝජනය' යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "සිතුවමට ප්‍රසන්න සුන්දරත්වය හා ලාලිත්‍යය එක් කිරීම", "සිතුවමේ මිල ගණන් තීරණය කිරීම", "බිත්තියට සිමෙන්ති ඇතිරීම", "වර්ණවල රසායනික විෂ ඉවත් කිරීම", "චිත්‍රයට කලාත්මක මෘදු බව, ආකර්ෂණය හා ලාලිත්‍යය මුසු කිරීම සම්භාව්‍ය කලා රීතියකි."),
        q("අනුරාධපුර කලාකරුවා බිතුසිතුවම් ඇඳීමට පෙර බිත්ති මතුපිට ආලේප කළ සිනිඳු සුදු ස්තරය හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "මකුළු මැටි හුණු ස්තරය", "තෙල් වාර්නිෂ් ස්තරය", "කළු තාර ස්තරය", "ලෝහ ආලේපන ස්තරය", "වර්ණ දීප්තිමත්ව පෙනීමට හා පින්සල පහසුවෙන් ගමන් කිරීමට සිනිඳු සුදු පසුබිම් ආලේපය යොදයි."),
        q("අනුරාධපුර යුගයේ බෞද්ධ සිතුවම් අතර 'පුල්ලිගොඩ' සිතුවම් කුමන යුගයකට අයත් සංක්‍රාන්ති ලක්ෂණ පෙන්වයිද?", "අනුරාධපුර අවසානය හා පොළොන්නරු මුල් යුගය", "ප්‍රාග් ඓතිහාසික හිම යුගය", "ලන්දේසි යටත්විජිත යුගය", "21 වන සියවසේ නූතන යුගය", "දිඹුලාගල ආසන්න පුල්ලිගොඩ ගල්ගෙයි දේව රූප අනුරාධපුර සම්භාව්‍ය ආරේ සිට පොළොන්නරු ආරට මාරු වීම පෙන්වයි."),
        q("සීගිරියේ පිහිටි 'ලෙන් අංක B' හි සිතුවම් විශේෂයෙන් කැපී පෙනෙන්නේ කුමන කලා අංගය නිසාද?", "ලාලිත්‍යමය හස්ත මුද්‍රා හා වලාකුළු අතරින් නැඟී සිටින ලලනා රූප", "කළුගලින් නෙළූ සමාධි බුදු රුව", "මහනුවර යුගයේ චක්‍රාවාට මණ්ඩලය", "සත්ව දඩයම් සිලුවට් රූප", "විශාලම හා පැහැදිලිවම සුරක්ෂිත සීගිරි අප්සරා යුගල හා තනි රූප බොහොමයක් B ලෙනේ දැකිය හැක."),
        q("අනුරාධපුර යුගයේ ධාතු ගර්භ බිතුසිතුවම්වල 'සත්ව රූප' ලෙස බහුලව ඇඳ තිබූ සංකේතාත්මක සතුන් මොනවාද?", "හංසයන්, ඇතුන් සහ සිංහයන්", "පෙන්ගුයින්, කැන්ගරු සහ සීබ්‍රා", "බයිසන් ගවයන් හා මැමත් ඇතුන්", "වෘකයන් සහ හිම වලසුන්", "ශුද්ධ බෞද්ධ සංකේත වූ ඇතා, සිංහයා, අශ්වයා හා හංස පෙළ මෝස්තර ධාතු ගර්භ සැරසිලිවල විය."),
        q("අනුරාධපුර යුගයේ බිතුසිතුවම්වල 'රූපවල දිශානතිය' බොහෝ විට තුන්කාල (Three-quarter) ඉරියව්වට යොමු කර ඇත්තේ ඇයි?", "මුහුණේ නාසය, දෑස් හා කම්මුල්වල ගැඹුර මනාව පෙන්වීමට", "සෑම රුවක්ම බිත්තියට හැරී සැඟවී සිටීමට", "වර්ණ ඉතිරි කර ගැනීමට එක් ඇසක් මකා දැමීමට", "රූප පැතලි කාඩ්බෝඩ් කැබලි මෙන් පෙන්වීමට", "සෘජු පැතිකඩට වඩා තුන්කාල පිහිටීම මගින් ජීවමාන ත්‍රිමාණ බවක් මුහුණට ලැබේ."),
        q("හිඳගල විහාරයේ බිතුසිතුවම්වල සක්‍ර දේවේන්ද්‍රයා නිරූපණය කර ඇති ඉරියව්ව කුමක්ද?", "පිරිවර සමඟ බුදුන් වහන්සේ වෙත පැමිණ ගෞරව දැක්වීම", "යුද රථයක නැගී සටන් කිරීම", "මල් උයනක නිදා සිටීම", "මහා සාගරයේ නැවක් පැදවීම", "ඉන්ද්‍රසාල ගුහාවේ වැඩ සිටි බුදුන් වහන්සේ හමුවට සක්‍රයා සහ පංචසිඛ පැමිණීම එහි දැක්වේ."),
        q("අනුරාධපුර යුගයේ සිතුවම් අතර 'ආරාම බිත්ති සිතුවම්' විනාශ වී යාමට බලපෑ ප්‍රධාන හේතුව කුමක්ද?", "ගඩොල් හා මැටි බිත්ති කාලගුණයෙන් හා යුද ආක්‍රමණවලින් විනාශ වීම", "සියලු විහාරවල සිතුවම් ඇඳීම තහනම් කර තිබීම", "එම යුගයේ සිතුවම් ඇන්දේ වැලි මත පමණක් වීම", "භික්ෂූන් වහන්සේලා සිතුවම් සෝදා හැරීම", "දැව හා ගඩොල් ආරාම දිරාපත් වීම නිසා ගල් ලෙන් හා ධාතු ගර්භ තුළ පමණක් සිතුවම් ඉතිරි විය."),
        q("සීගිරි සිතුවම්වල භාවිත කළ 'ටෙරා වර්ට්' කොළ වර්ණය බහුලව යොදාගෙන ඇත්තේ කුමන කොටස් වර්ණ ගැන්වීමටද?", "පසුබිම් කොළ අතු, වලාකුළු ඡායා හා ඇඳුම් පටි", "කාන්තාවන්ගේ දෑස්වල කළු ඉංගිරියාව", "නෙළුම් මල්වල සුදු පෙති", "රන් ඔටුණුවල දිලිසෙන කොටස්", "මල්වල නටු, කොළ සහ අඳුරු පැහැ කාන්තාවන්ගේ සමේ හා සළුවල සමහර කොටස් සඳහා කොළ පැහැය යොදා ඇත."),
        q("අනුරාධපුර යුගයේ 'මුල් සම්භාව්‍ය සිතුවම්වල' රේඛා ස්වභාවය පිළිබඳ නිවැරදි ප්‍රකාශය කුමක්ද?", "ඝනකම අඩු වැඩි වන රිද්මයානුකූල හා නම්‍යශීලී රේඛා", "එකම පළලින් යුත් කෝදු කෙළින් රේඛා", "සම්පූර්ණයෙන් කැඩී ගිය තිත් රේඛා පමණි", "රළු පිහි තුඩකින් කැපූ කෝණික රේඛා", "චිත්‍ර ශිල්පියාගේ හස්ත චලනය අනුව රේඛාව සිහින් හා මහත් වෙමින් ජීවමාන බව මවයි."),
        q("මිහින්තලේ කණ්ඨක චේතියේ හා රුවන්වැලිසෑයේ වාහල්කඩ සැරසිලි මත තිබූ වර්ණ ලපවලින් හෙළි වන්නේ කුමක්ද?", "පුරාණ ගල් කැටයම් හා ස්තූප පවා වර්ණාලේප කර තිබූ බව", "වන්දනාකරුවන් තීන්ත බාල්දි හැලූ බව", "වාහල්කඩ මෑතකදී ප්ලාස්ටික් තීන්ත ගෑ බව", "ගල්වල ස්වභාවිකව මලකඩ බැඳුණු බව", "සුදු හුණු පිරියම් මත රතු, කහ සහ කොළ වර්ණවලින් ගල් කැටයම් පවා වර්ණවත් කර තිබී ඇත."),
        q("සීගිරි සිතුවම්වල ඇඳ ඇති කාන්තා රූප 'ඉන්දීය අජන්තා සිතුවම්වලට වඩා' රේඛාමය නිදහසකින් යුක්ත යැයි කියන්නේ ඇයි?", "අනවශ්‍ය සැරසිලි හා බර ගතියෙන් තොර සරල සජීවී රේඛාව නිසා", "අජන්තාවේ කිසිදු රේඛාවක් භාවිත නොකළ නිසා", "සීගිරියේ පින්සල් වෙනුවට ඇඟිලි යොදාගත් නිසා", "සීගිරි සිතුවම් සියල්ල කළු සුදු පමණක් වන නිසා", "සීගිරි රූපවල ඉරියව් හා සිරුරු රේඛා අජන්තාවට වඩා සරල හා ප්‍රාණවත් බවක් දරයි."),
        q("අනුරාධපුර සමයේ 'බිතුසිතුවම් ශිල්පියා' සමාජයේ හැඳින්වූයේ හා ගෞරවයට පාත්‍ර වූයේ කෙසේද?", "චිත්තකාර හෙවත් ශිල්පීය ආචාර්යවරයෙකු ලෙස", "රාජ්‍ය බදු එකතු කරන්නෙකු ලෙස", "කුලී කම්කරුවෙකු ලෙස පමණි", "විදේශීය තානාපතිවරයෙකු ලෙස", "පැරණි සෙල්ලිපි හා වංශකතාවල චිත්‍ර ශිල්පීන් 'චිත්තකාර' ලෙස ගෞරවයෙන් සඳහන් වේ."),
        q("මහාවංශයේ සඳහන් වන පරිදි ලෝවාමහාපාය හා ජේතවනාරාමය වැනි විහාරවල චිත්‍ර ඇඳ තිබූ බවට හමුවන සාහිත්‍යමය සාධක මොනවාද?", "සත්සතිය, මාර පරාජය හා වෙස්සන්තර ජාතකය සිතුවම් කිරීම ගැන විස්තර", "චීන අධිරාජ්‍යයන්ගේ යුද ජයග්‍රහණ විස්තර", "බ්‍රිතාන්‍ය ආණ්ඩුකාරවරුන්ගේ නම් ලැයිස්තු", "ග්‍රීක දේව කතා විස්තර", "ලක්දිව මහා විහාර බිත්ති බෞද්ධ සිතුවම්වලින් සරසා තිබූ බව මහාවංශයේ හා ථූපවංශයේ දැක්වේ."),
        q("අනුරාධපුර යුගයේ බිතුසිතුවම්වල 'රතු ගුරුගල්' වර්ණයට අමතරව දීප්තිමත් රතු පැහැය සඳහා යොදා ගත් ඛනිජය කුමක්ද?", "සාදිලිංගම් (Cinnabar)", "කොපර් සල්ෆේට්", "කැල්සියම් කාබනේට්", "සෝඩියම් ක්ලෝරයිඩ්", "රසදිය සල්ෆයිඩ් අඩංගු සාදිලිංගම් දීප්තිමත් රතු පැහැය ලබා ගැනීමට පුරාණ සිත්තරු යොදා ගත්හ."),
        q("සීගිරියේ පර්වත බිත්තියට ඉහළින් කටාරමක් කොටා තිබීම නිසා සිතුවම්වලට ලැබුණු ප්‍රධාන රැකවරණය කුමක්ද?", "පර්වත මුදුනෙන් ගලා එන වැසි ජලය බිතුසිතුවම් මත වැටීම වැළකීම", "හිරු එළිය සම්පූර්ණයෙන් ගුහාව තුළට ඇද ගැනීම", "කුරුල්ලන්ට කූඩු සෑදීමට ඉඩ සැලසීම", "රාජ සභාව පැවැත්වීමට ආසන සැදීම", "පුරාණ කටාරම් නිර්මාණය වැසි දියෙන් බදාමය සේදී යාම වැළැක්වීමේ දියුණු ඉංජිනේරු ක්‍රමයකි."),
        q("හිඳගල බිතුසිතුවම් හා සීගිරි බිතුසිතුවම් 'සංයුතිය' (Composition) අතින් වෙනස් වන්නේ කෙසේද?", "හිඳගල කතා පුවතක් නිරූපණය වන අතර සීගිරියේ තනි හා යුගල දිව්‍ය රූප වේ", "හිඳගල සතුන් පමණක් වන අතර සීගිරියේ ගස් පමණක් වේ", "හිඳගල ජ්‍යාමිතික රටා පමණක් වේ", "දෙකෙහිම එකම රූප පිටපත් කර ඇත", "හිඳගල බෞද්ධ ආඛ්‍යාන සංයුතියක් වන අතර සීගිරිය සෞන්දර්යමය දේව රූප සංයුතියකි."),
        q("අනුරාධපුර සම්භාව්‍ය බිතුසිතුවම්වල කාන්තා හා දේව රූපවල ඇඳ ඇති 'නෙත් හා දෙතොල්' මගින් ප්‍රකාශ වන රසය කුමක්ද?", "ශාන්ත රසය හා සෞම්‍ය කරුණා රසය", "භයානක හා බිහිසුණු රසය", "රෞද්‍ර හා කෝප රසය", "හාස්‍ය හා උපහාස රසය", "උත්තරීතර ශාන්තභාවය හා මෘදු ආකර්ෂණය පෙරදිග සම්භාව්‍ය සිතුවම්වල ප්‍රධාන ලක්ෂණයකි."),
        q("මහියංගණ දාගැබේ ධාතු ගර්භ සිතුවමේ 'ශිව හා විෂ්ණු' වැනි දේව රූප බුදුන් වහන්සේ අසල ඇඳ තිබීමෙන් පෙනෙන සංස්කෘතික කරුණ කුමක්ද?", "බුදුන් වහන්සේට ගෞරව කරන පරිවාර දෙවිවරුන් ලෙස දේව සංකල්ප බෞද්ධ කලාවට එක්වීම", "විහාරය හින්දු කෝවිලක් ලෙස පැවති බව", "කලාකරුවා වැරදීමකින් වෙනත් රූප ඇඳි බව", "බුදු රුව සම්පූර්ණයෙන් අමතක කළ බව", "බෞද්ධ සාහිත්‍යය අනුව බෝධි මූලයේදී හා දේවාරාධනාවේදී දෙවිවරුන් පැමිණි බව මෙයින් නිරූපණය වේ."),
        q("අනුරාධපුර යුගයේ චිත්‍ර ශිල්පීන් 'වර්ණක ඇඹරීම' සඳහා භාවිත කළ බන්ධක හා ද්‍රව මොනවාද?", "දිවුල් ලාටු, කොහොඹ මැලියම් සහ පිරිසිදු ජලය", "ඛනිජ තෙල් සහ ඇසිටෝන්", "කෘත්‍රිම රබර් ද්‍රාවණ", "විනාකිරි සහ සබන් වතුර", "ස්වභාවික ශාක මැලියම් වර්ණ කුඩු බදාමයට තදින් බැඳ තබා ගැනීමට උපකාරී විය."),
        q("සීගිරි සිතුවම් ලෙනෙහි පවතින 'ලලනාවකගේ නෙළුම් මල් අතේ තබා ගැනීමේ ඉරියව්ව' හඳුන්වනු ලබන පෙරදිග මුද්‍රාවට සමාන ඉරියව්ව කුමක්ද?", "කටක මුද්‍රාව (Kataka Mudra)", "අභය මුද්‍රාව", "භූමිස්පර්ශ මුද්‍රාව", "ධර්මචක්‍ර මුද්‍රාව", "මලක නටුව සියුම්ව ඇඟිලිවලින් අල්ලාගෙන සිටින විලාසය නර්තන හා මූර්ති කලාවේ කටක මුද්‍රාවට සමානය."),
        q("අනුරාධපුර යුගයේ බිතුසිතුවම් තුළ 'රාජ්‍ය හා ආගමික අනුග්‍රහය' කොතරම් වැදගත් වීද යත්?", "රජවරුන්ගේ ධනය හා සංවිධානය නිසා උසස් තාක්ෂණික චිත්‍ර බිහිවීම", "චිත්‍ර ඇඳීම සාමාන්‍ය ජනයාට තහනම් වීම", "රජවරුන් විසින් සියලු පැරණි චිත්‍ර මකා දැමීම", "චිත්‍ර ශිල්පීන්ට කිසිදු පහසුකමක් නොදීම", "කාශ්‍යප හා දුටුගැමුණු වැනි රජවරුන්ගේ අනුග්‍රහයෙන් උසස්ම ඛනිජ හා දක්ෂ ශිල්පීන් යොදා ගැනිණි."),
        q("වෙස්සගිරි ලෙන් බිතුසිතුවම් ශේෂ අධ්‍යයනයේදී හමුවූ 'ලියවැල් හා මල් මෝස්තර' පෙන්වා දෙන්නේ කුමක්ද?", "රූප සිතුවම් මෙන්ම සැරසිලි මෝස්තර කලාවද අනුරාධපුරයේ දියුණු වූ බව", "මහනුවර යුගයේදී වෙස්සගිරිය ඉදිකළ බව", "සතුන්ගේ රූප ඇඳීම සම්පූර්ණයෙන් තහනම් වූ බව", "ගස් වැල්වලට තීන්ත ගෑ බව", "සංඝාවාස ලෙන් සිවිලිම පවා රතු හා කහ පැහැති සියුම් මල් මෝස්තරවලින් සරසා තිබී ඇත."),
        q("අනුරාධපුර යුගයේ 'පුල්ලිගොඩ ගල්ගෙයි' සිතුවමේ සිටින රැවුල සහිත පුද්ගලයන් හා දේව රූපවල ඇඳුම් පැළඳුම් කෙබඳුද?", "සුදු උරපටි හා හිස් ජටා සහිත දිව්‍ය හෝ සෘෂි රූප", "මහනුවර මුල් ඇඳුම හා තුප්පොට්ටිය", "පෘතුගීසි කබා හා තොප්පි", "නූතන කලිසම් හා කමිස", "දිගටි උරපටි, කුණ්ඩලාභරණ හා සරල හිස් ජටා සහිත දේව හෝ ශ්‍රාවක රූප පස්දෙනෙකු එහි දැක්වේ."),
        q("සීගිරි බිතුසිතුවම්වල 'අඳුරු පැහැ කාන්තාවන්' කෙටි කෙස් කළඹකින් හා සරල ඇඳුමින් දැක්වීමට හේතුව කුමක් විය හැකිද?", "පරිවාර සේවිකාවන් හා ප්‍රධාන කුමරියන් අතර තත්ත්ව වෙනස පෙන්වීමට", "සිතුවම් ශිල්පියාට රන් පැහැය අවසන් වූ බැවින්", "කොණ්ඩය ඇඳීමට අමතක වූ බැවින්", "වෙනත් රටක සොල්දාදුවන් දැක්වීමට", "රන්වන් කුමරියන්ට අභිෂේක ආභරණ වැඩිපුර යොදා සේවිකාවන් ඊට වඩා චාම් ලෙස ඇඳ ඇත."),
        q("අනුරාධපුර යුගයේ චිත්‍ර කලාව හා භාරතීය ගුප්ත යුගයේ චිත්‍ර කලාව අතර පවතින සමානකම කුමක්ද?", "දිව්‍යමය සෞන්දර්යය, ත්‍රිභංග ඉරියව්ව හා මෘදු වර්ණ ශ්‍රේණිගත කිරීම", "තෙල් සායම් හා ඉම්පැස්ටෝ ආලේපනය", "සම්පූර්ණ වියුක්ත ජ්‍යාමිතික හැඩතල", "පැතලි කොමික් චිත්‍ර පෙළ", "ක්‍රි.ව. 4–6 සියවස්වල භාරතීය ගුප්ත සම්ප්‍රදාය හා සීගිරි-හිඳගල සම්ප්‍රදාය අතර සමීප සබඳතාවක් වේ."),
        q("සීගිරියේ ලෙන් බිතුසිතුවම් 'සජීවී ස්පර්ශයකින්' යුක්ත වීමට බලපෑ චිත්‍රමය අංගය කුමක්ද?", "මඳ සිනහව, දිගටි දෑස් හා චලනය වන අත් ඉරියව්", "දැඩි හතරැස් මුහුණු හා කෙළින් ඇස්", "කළු පැහැති බෝඩර් රාමු", "සමතලා අළු පසුබිම", "මුහුණේ මෘදු භාව ප්‍රකාශනය හා සජීවී අත් චලනය රූපවලට පණ දෙන බව විචාරකයෝ පෙන්වා දෙති."),
        q("අනුරාධපුර කලා යුගයේ 'බිතුසිතුවම් සංරක්ෂණය' සඳහා පුරාණ ශිල්පීන් යොදා ගත් ඉතා සාර්ථක පිළියම කුමක්ද?", "සවිමත් හුණු-මැටි බදාමය හා පර්වත ආරක්ෂිත ලෙන් තෝරා ගැනීම", "ප්ලාස්ටික් වාර්නිෂ් තට්ටු දහයක් ගෑම", "සිතුවම් මත වීදුරු පෙට්ටි සවි කිරීම", "වසරක් පාසා සිතුවම් මත අලුත් තීන්ත ගෑම", "ජලය හා දිලීර ඔරොත්තු දෙන ස්වාභාවික හුණු බදාම තාක්ෂණය සියවස් ගණනක් චිත්‍ර ආරක්ෂා කළේය."),
        q("සීගිරි ලෙන් සිතුවමක සිටින එක් අප්සරාවක් අත 'දම් හෝ රතු පැහැති මලක්' දරා සිටින අතර ඇගේ දකුණු අත පෙන්වන විලාසය කුමක්ද?", "මල් පෙති කඩා පූජා කිරීමට හෝ ඉසීමට සූදානම් වන අයුරු", "අසිපතක් ඉහළට ඔසවා සිටින අයුරු", "පොතක් කියවමින් සිටින අයුරු", "බෙරයක් වාදනය කරන අයුරු", "මල් නෙළන හා ඉසින අභිනය රූපවල ඇති සුන්දරම චලන අවස්ථාවකි."),
        q("අනුරාධපුර යුගයේ චිත්‍ර කලාවේ 'වර්ණකවල රසායනික ස්ථාවරත්වය' තහවුරු වී ඇත්තේ කෙසේද?", "වසර 1500කට පසුවත් සීගිරි රතු හා කහ පැහැයන් නොනැසී පැවතීමෙන්", "සිතුවම් සියල්ල කළු පැහැයට හැරී තිබීමෙන්", "වර්ණ සියල්ල පසුගිය වසරේ නැවත පින්තාරු කිරීමෙන්", "සිතුවම් වීදුරු යට නිර්මාණය කර තිබීමෙන්", "ස්වාභාවික ඛනිජ වර්ණක සූර්යාලෝකයට හා කාලයට ඔරොත්තු දෙන බව සීගිරි සිතුවම් ඔප්පු කරයි."),
        q("සීගිරිය පර්වතයේ ඇති 'මහා ශිලා මණ්ඩප' හා ජල පොකුණු අසල ගල්වල පැරණි බදාම හමුවීමෙන් පෙනෙන කරුණ කුමක්ද?", "සීගිරියේ ලෙනට අමතරව ගොඩනැගිලි බිත්තිද වර්ණවත් සිතුවමින් සරසා තිබූ බව", "මුළු කන්දම කොළ තීන්තවලින් වසා තිබූ බව", "සීගිරියේ කිසිදු ගොඩනැගිල්ලක් නොතිබූ බව", "කාශ්‍යප රජු චිත්‍ර ඇඳීම නතර කළ බව", "මාලිගා බිත්ති හා ආසන ගල් පවා අලංකාර හුණු පිරියම් හා සිතුවමින් යුක්ත වූ බව කැණීම් පෙන්වයි."),
        q("හිඳගල විහාරයේ බිතුසිතුවම් 'සීගිරියට පසු යුගයක' නිර්මාණය වූ බවට ඇති ශෛලිමය සාධකය කුමක්ද?", "සීගිරි රේඛා ආරට වඩා මඳක් සරල වූ හා බෞද්ධ ආඛ්‍යාන මුසු වූ ලක්ෂණ", "සිංහල මුද්‍රිත අකුරු පුවරු තිබීම", "බටහිර යථාර්ථවාදී ඡායාරූප ශෛලිය", "ඇක්‍රිලික් වර්ණ තට්ටු පැවතීම", "සීගිරියෙන් පසු ක්‍රි.ව. 7 වන සියවස දෙසට බෞද්ධ කතා පුවත් ශෛලියක් ලෙස වර්ධනය විය."),
        q("අනුරාධපුර යුගයේ චිත්‍ර කලාවේදී 'මුහුණුවල භාව ප්‍රකාශනය' සඳහා ඇහිබැම, ඇස් සහ තොල් හසුරුවා ඇති ආකාරය කෙබඳුද?", "සිහින් රේඛාවලින් සියුම් මානසික ශාන්තිය හා කරුණාව පළ කිරීම", "ඝන ඉරිවලින් විකට හා හාස්‍ය මුහුණු සෑදීම", "සියලු මුහුණු එකම අච්චුවකින් මුද්‍රණය කිරීම", "මුහුණුවල ඇස් හා කට නොඇඳ හිස්ව තැබීම", "මඳ සිනහවක් හා අඩවන් දෙනෙත් තුළින් ගැඹුරු ආධ්‍යාත්මික හා සෞන්දර්ය ශාන්තිය මතු කරයි."),
        q("සීගිරි ලෙන් සිතුවම්වල 'බදාම ස්තරය' සකස් කිරීමේදී යොදා ගත් අමුද්‍රව්‍ය අතර අදටත් පෙනෙන රළු සංඝටකය කුමක්ද?", "වී පොතු හෙවත් දහයියා කැබලි", "ප්ලාස්ටික් කැබලි", "වීදුරු කුඩු කැබලි", "යකඩ කම්බි කැබලි", "බිඳී ගිය බදාම කොටස්වල රතු මැටි සමඟ මිශ්‍ර කළ දහයියා කැබලි පැහැදිලිව දැකිය හැක."),
        q("අනුරාධපුර රජරට කලා ශිල්පීන් භාවිත කළ 'රන්වන් කහ' වර්ණකයට සිංහල සාම්ප්‍රදායික කලාවේ කියන නම කුමක්ද?", "හිරියල් හෝ ගොකටු කිරි", "නිල් අවරිය", "කළු අඟුරු", "සාදිලිංගම්", "ඛනිජ හිරියල් සහ ගොකටු ගසේ කිරි සාම්ප්‍රදායික කහ වර්ණක ලෙස භාවිත විය."),
        q("සීගිරි සිතුවම්වල කාන්තා රූපවල ඉඟටියේ සිට පහළට ඇඳ ඇති 'සළු පොටවල්' වලින් කලා කෘතියට ලැබෙන උපකාරය කුමක්ද?", "චලනයේ දිශාව හා ආකාශගාමී පාවෙන බව තීව්‍ර කිරීම", "රූප සම්පූර්ණයෙන් බිම වාඩි වී සිටින බව පෙන්වීම", "වස්තූන්වල බර වැඩි කර පෙන්වීම", "බිත්තියේ දෝෂ වැසීම පමණක්", "සුළඟේ ලෙළදෙන සේ ඇඳි සළු පටි සීගිරි ලලනාවන්ගේ ගමන් රිද්මය මතු කරයි."),
        q("අනුරාධපුර යුගයේ චිත්‍ර කලාව 'ශ්‍රී ලාංකේය ජාතික අනන්‍යතාවට' වැදගත් වන්නේ කෙසේද?", "විදේශ ආභාසය ලැබුවද ස්වාධීන දේශීය රේඛා හා වර්ණ ශෛලියක් ගොඩනැගූ බැවින්", "සම්පූර්ණයෙන්ම විදේශීය චිත්‍ර පිටපත් කර තැබූ බැවින්", "කිසිදු දේශීය මලක් හෝ සංස්කෘතික අංගයක් නොගත් බැවින්", "නූතන යුරෝපීය කලාවට වඩා පසුව බිහි වූ බැවින්", "අජන්තා සම්ප්‍රදාය හා සමානකම් තිබුණද සීගිරිය හෙළ කලා ශිල්පියාගේ ස්වාධීන ප්‍රතිභාව ප්‍රකට කරයි."),
        q("මිහින්තලේ කණ්ඨක චේතියේ හා අභයගිරි විහාර ධාතු ගර්භවල බිතුසිතුවම් අධ්‍යයනයෙන් හෙළි වන 'දේව රූප ශෛලිය' කුමක්ද?", "සීගිරි සම්ප්‍රදායේ අඛණ්ඩ විකාශනයක් පෙන්නුම් කිරීම", "ප්‍රාග් ඓතිහාසික කූරු රූප බවට ආපසු යාම", "චීන සෙරමික් රූප අනුකරණය කිරීම", "මහනුවර පැතලි චිත්‍ර ආරට හැරීම", "ධාතු ගර්භවල දේව රූපවලද සීගිරියේ දක්නට ලැබුණු ත්‍රිමාණ වර්ණ ආලේපනය හා රේඛා ලාලිත්‍යය දක්නට විය."),
        q("සීගිරියේ බිතුසිතුවම් ගලෙන් ගැලවී යාම වැළැක්වීමට නූතන පුරාවිද්‍යා සංරක්ෂකයන් කරන නිතිපතා කාර්යය කුමක්ද?", "බදාමයේ බුබුළු හා ඉරිතැළීම් එන්නත් මගින් තහවුරු කිරීම (Grouting)", "සෑම වසරකම අලුත් තීන්ත ආලේප කිරීම", "සිතුවම් ප්ලාස්ටික් ශීට්වලින් සම්පූර්ණයෙන් ඇලවීම", "බිත්තිවලට ජලය ඉස සේදීම", "පුරාවිද්‍යා සංරක්ෂණයේදී ගල හා බදාමය අතර හිඩැස් පිරවීමට විශේෂ හුණු මිශ්‍රණ එන්නත් කරනු ලැබේ."),
        q("සීගිරි අප්සරාවන්ගේ මුහුණුවල 'මෘදු සෙවණැලි' දැක්වීම සඳහා භාවිත කළ වර්ණ තාක්ෂණය කුමක්ද?", "රතු-දුඹුරු හා කහ පැහැය සියුම්ව එකිනෙක මුසු කිරීම", "කළු තිත් විශාල වශයෙන් ගැසීම", "සුදු පැහැති කෙළින් ඉරි ඇඳීම", "නිල් පැහැති වළලු ඇඳීම", "වර්ණ ශ්‍රේණිගත කර මුසු කිරීමෙන් (Blending) මුහුණේ හා ගෙලේ රවුම් බව දක්වා ඇත."),
        q("අනුරාධපුර යුගයේ දිඹුලාගල ප්‍රදේශයේ පුල්ලිගොඩ ගුහා සිතුවමේ සිටින දේව රූප 'බෞද්ධ සිතුවම්' බව හඳුනා ගන්නේ කෙසේද?", "වටා ඇති ප්‍රභා මණ්ඩල (Halos) සහ නමස්කාර හස්ත ඉරියව්වලින්", "කඩු හා පළිහ අත දරා සිටීමෙන්", "වෙළඳ බඩු ගෝණි රැගෙන යාමෙන්", "රෝම සෙබළ ඇඳුම් ඇඳ සිටීමෙන්", "රැස් වළලු සහ පූජනීය ඉරියව් මගින් බුදුන් හෝ ශාසනය වඳින දෙවිවරුන් නිරූපිතය."),
        q("අනුරාධපුර යුගයේ චිත්‍ර කලාවේ 'මහාසම්ප්‍රදාය' ලෙස සැලකෙන සීගිරිය හා හිඳගල සිතුවම්වල පොදු ගුණාංගය කුමක්ද?", "සම්භාව්‍ය පරිමාව, නිදහස් රේඛාව සහ ශාන්ත භාව ප්‍රකාශනය", "තීරු ක්‍රමය හා පැතලි රතු පසුබිම", "වියුක්ත ජ්‍යාමිතික රටා පමණක් වීම", "කළු සහ සුදු පැහැයෙන් පමණක් ඇඳීම", "රේඛාමය ශක්තිය හා මානව රූපවල ජීවමාන පරිමාව අනුරාධපුර සම්භාව්‍ය සිතුවම්වල ප්‍රධාන ලක්ෂණයයි."),
        q("සීගිරි සිතුවම්වල පෙනෙන 'අප්සරාවකගේ ඉණට පහළින් ඇඳ ඇති වලාකුළු' සිතුවම් සංයුතියට කරන බලපෑම කුමක්ද?", "පහළ කොටසේ රූපවලට සමබර පදනමක් ලබා දීම", "රූපවල හිස් සම්පූර්ණයෙන් වැසීම", "චිත්‍රය අඳුරු හා බියකරු කිරීම", "මුළු පර්වතයම වැසි වලාකුළකින් වැසීම", "වක්‍ර වලාකුළු රේඛා රූපවල සිරස් බවට සමබර තිරස් පදනමක් සපයයි."),
        q("රුවන්වැලිසෑය හා මිහින්තලය වැනි ස්ථානවල පැවති 'ධාතු ගර්භ බිතුසිතුවම්' සාමාන්‍ය ජනයාට නැරඹීමට ඉඩ නොලැබුණේ ඇයි?", "ඒවා ධාතූන් වහන්සේලා තැන්පත් කර සදහටම වසා දැමූ කුටි තුළ ඇඳි බැවින්", "ඒවා විදේශීය රටවල පිහිටි බැවින්", "එම සිතුවම් ඉතා කුඩා ක්ෂුද්‍ර රූප වූ බැවින්", "ඒවා මුහුද යට ගොඩනැගූ බැවින්", "ධාතු ගර්භ සිතුවම් මිනිසුන්ට පෙන්වීමට වඩා ධාතූන් වහන්සේට පූජාවක් ලෙස නිමැවිණි."),
        q("මහියංගණ ධාතු ගර්භයේ සිතුවම්වල බුදුරජාණන් වහන්සේගේ උස හා පරිවාර දේව රූපවල උස අතර ඇති වෙනස කුමක්ද?", "බුදු රුව ප්‍රධානත්වය හඟවන සේ අනෙක් රූපවලට වඩා විශාලව ඇඳ තිබීම", "දෙවිවරුන් බුදු රුවට වඩා දස ගුණයක් විශාලව ඇඳ තිබීම", "සියලුම රූප එකම සෙන්ටිමීටර ප්‍රමාණයෙන් ඇඳ තිබීම", "බුදු රුව ඉතා කුඩා තිතක් ලෙස ඇඳ තිබීම", "ආගමික ගෞරවය හා ප්‍රධානත්වය දැක්වීමට ශ්‍රේණිගත පරිමාණය යොදාගෙන ඇත."),
        q("අනුරාධපුර යුගයේ චිත්‍ර කලාව පිළිබඳව ලියැවුණු 'චිත්‍රසූත්‍රය' හෙවත් භාරතීය ශාස්ත්‍රීය කලා ග්‍රන්ථයේ මූලධර්ම මෙරටට බලපෑවේ කෙසේද?", "වර්ණ භාවිතය, ප්‍රමාණ විද්‍යාව හා භාව නිරූපණ රීති තුළින්", "තෙල් සායම් නිෂ්පාදන ක්‍රම හඳුන්වා දීමෙන්", "වීදුරු මූර්ති තාක්ෂණය ඉගැන්වීමෙන්", "නූතන ඡායාරූප කැමරා ශිල්පය ලබා දීමෙන්", "දකුණු ආසියාතික බෞද්ධ කලා සම්ප්‍රදායේ පොදු න්‍යායන් අනුරාධපුර ශිල්පීන්ගේ නිර්මාණවලද දැකිය හැක."),
        q("සීගිරි කලාගාරයේ 'පර්වත මතුපිට තෝරා ගැනීමේදී' ලෙන් බිත්තියට ඉහළින් කාශ්‍යප රජු කළ ඉදිකිරීම කුමක්ද?", "වැසි දිය පාලනයට කටාරම් කෙටීම හා බදාම සැකසීම", "ලෙන ඉදිරිපිට උස තාප්පයක් බැඳ ලෙන සම්පූර්ණයෙන් වැසීම", "පර්වතය මුදුනේ විශාල වීදුරු වහලයක් තැනීම", "වැවක් කපා ලෙන තුළට ජලය හැරවීම", "කටාරම් කෙටීම සහ කැටපත් පවුර මගින් ලෙන කරා ආරක්ෂිත පිවිසුමක් සකසා තිබිණි."),
        q("අනුරාධපුර යුගයේ සිතුවම්වල 'නෙළුම් මල් මෝස්තරය' බහුලව යොදා ගැනීමට හේතු වූ ආගමික සංකේතාර්ථය කුමක්ද?", "පවිත්‍රතාව, නිර්වාණය සහ බුදු දහමේ උත්තරීතර බව", "වෙළඳ ව්‍යාපාරවල ලාභය", "යුද ජයග්‍රහණයේ කෲර බව", "සතුන් දඩයම් කිරීමේ උත්සවය", "මඩෙන් නැඟී සුවඳවත් වන නෙළුම බෞද්ධ කලාවේ ප්‍රධාන පවිත්‍රතා සංකේතයයි."),
        q("සීගිරියේ ඇති 'කැටපත් පවුර' මත සීගිරි සිතුවම් දැක ලියූ කවි අතර 'වීණාවක් අතින් ගත්' හෝ විවිධ ලලනාවන් ගැන සඳහන් වීමෙන් පෙනෙන්නේ කුමක්ද?", "අතීතයේ තවත් විවිධ ඉරියව් සහිත සිතුවම් රැසක් එහි තිබූ බව", "සීගිරියේ පැරණි සංගීත පාසලක් තිබූ බව", "සිතුවම් සියල්ල කට වචනයෙන් කියූ කතා බව", "වීණා කැටයම් ගල මත කොටා තිබූ බව", "කාලයත් සමඟ මැකී ගිය තවත් සිතුවම් ගණනාවක තොරතුරු කුරුටු ගීවල සුරැකී පවතී."),
        q("හිඳගල බිතුසිතුවම්වල භාවිත කර ඇති ප්‍රධාන වර්ණ මාලාව කුමක්ද?", "රතු, කහ, කොළ, කළු සහ සුදු පෘථිවි වර්ණ", "රෝස, දම්, රිදී සහ නියෝන් වර්ණ", "තද නිල් සහ දීප්තිමත් රන් තීන්ත පමණි", "තනි කළු අඟුරු පමණි", "අනුරාධපුර සම්ප්‍රදායට අනුව ස්වභාවික ඛනිජ වර්ණ පුවරුව හිඳගලද භාවිත කර ඇත."),
        q("අනුරාධපුර යුගයේ බිතුසිතුවම් හා ඒවායේ ඓතිහාසික වැදගත්කම පිළිබඳව නිවැරදි ප්‍රකාශය කුමක්ද?", "ශ්‍රී ලංකාවේ චිත්‍ර කලා ඉතිහාසයේ සම්භාව්‍ය ස්වර්ණමය යුගය සනිටුහන් කිරීම", "චිත්‍ර කලාවේ පරිහානි යුගය සනිටුහන් කිරීම", "යුරෝපීය යටත්විජිත සමය ආරම්භ කිරීම", "කිසිදු ශිල්පීය වටිනාකමක් නොතිබීම", "සීගිරිය, හිඳගල සහ ධාතු ගර්භ සිතුවම් ලාංකේය චිත්‍ර කලාවේ සම්භාව්‍ය යුගය ලොවට පෙන්වයි."),
        q("සීගිරි බිතුසිතුවම්වල ඇඳ ඇති සමහර කාන්තාවන්ගේ 'අත්වල රත් පැහැය' (මදටිය පැහැය) හඳුනා ගැනීමෙන් එවකට පැවති කුමන චාරිත්‍රයක් ගැන අදහසක් ලැබේද?", "අලංකරණය සඳහා නිය හා අත්ල වර්ණ ගැන්වීමේ රූපලාවණ්‍ය සිරිත", "රෝගීන්ට බෙහෙත් පැලැස්තර දැමීම", "තීන්ත වැඩිපුර ඉතිරි වීම නිසා පිස දැමීම", "රණශූරයන්ගේ ලේ තැවරීම", "කාන්තාවන් අත්ල හා ඇඟිලි තුඩු මදටිය හෝ ලාක්ෂා පැහැයෙන් සැරසීම සම්භාව්‍ය විලාසිතාවක් විය."),
        q("අනුරාධපුර යුගයේ සිතුවම්වල 'රූපයේ පසුපස කොටස වලාකුළින් වැසීම' මගින් සීගිරි ශිල්පියා විසඳා ගත් කලාත්මක ගැටලුව කුමක්ද?", "අසම්පූර්ණ වක්‍ර බිත්ති තලය තුළ රූප ස්වභාවිකව අවසන් කිරීම", "රූපවලට සපත්තු ඇඳීමට නොහැකි වීම", "කාන්තාවන්ට කකුල් ඇඳීමට නොදැන සිටීම", "පසුබිමේ වැව් පොකුණු සැඟවීම", "කුඩා හා වක්‍ර බිත්ති කුටීරයේ රූප අලංකාරව අවසන් කරමින් ආකාශගාමී බව මවා ඇත."),
        q("සීගිරියේ ඇති 'ලෙන් අංක A' හි දක්නට ලැබෙන රූපවල ශෛලිය හා වර්ණ අනුව එය සමස්ත කලාගාරයේ කුමන කොටසක්ද?", "ප්‍රධාන ලෙනට ඉහළින් හෝ අසලින් ඇති උසස් සීගිරි සිතුවම් කොටසකි", "මහනුවර යුගයේ අලුතින් ඇඳි ශාලාවකි", "ප්‍රාග් ඓතිහාසික වැදි සිතුවම් කුටියකි", "කැටපත් පවුරේ පහළ කොටසකි", "A සහ B ලෙන් දෙකෙහිම අනුරාධපුර සීගිරි ලලනාවන්ගේ අග්‍රගණ්‍ය සිතුවම් සංරක්ෂිතය."),
        q("අනුරාධපුර යුගයේ 'විහාර ආරාම බිතුසිතුවම්' ඇඳීමේ ප්‍රධානතම අරමුණ කුමක් වීද?", "ශ්‍රද්ධාව වැඩීම, ධර්මය සන්නිවේදනය හා විහාර අලංකරණය", "රාජ්‍ය නීති හා බදු ගිවිසුම් ප්‍රසිද්ධ කිරීම", "වෙළඳ දැන්වීම් ප්‍රචාරය කිරීම", "යුද රහස් සතුරන්ගෙන් සැඟවීම", "බුදු සිරිත හා ජාතක කතා දෘශ්‍ය මාධ්‍යයෙන් ජනතාවට ඉගැන්වීම විහාර සිතුවම්වල මූලික අරමුණ විය."),
        q("අනුරාධපුරයේ 'මිහින්තලේ' හා 'රුවන්වැලිසෑය' ධාතු ගර්භ සිතුවම්වල වැඩි වශයෙන් යොදාගෙන ඇති රේඛා ක්‍රමය කුමක්ද?", "නිදහස් චාලන රේඛා හා මෘදු සෙවණැලි ආලේපනය", "ඉංජිනේරුමය ජ්‍යාමිතික රේඛා පමණි", "රළු අඟුරු සීරුම් ඉරි", "පැතලි කොටු දැල් රේඛා", "සම්භාව්‍ය අනුරාධපුර ශෛලියට අනුව ජවසම්පන්න රේඛා හා මෘදු වර්ණ මිශ්‍රණය එහි විය."),
        q("සීගිරි බිතුසිතුවම්වල ඇඳ ඇති කාන්තා රූප 'යුගල' ලෙස පෙනෙන විට ප්‍රධාන රුව ඉදිරියෙන්ද සේවිකාව පසුපසින්ද තැබීමෙන් ඇති වන අවකාශමය හැඟීම කුමක්ද?", "පෙරදිග ඉදිරිපස-පසුපස අවකාශ ගැඹුර (Overlapping depth)", "සියලු රූප එකම පැතලි රේඛාවක තැබීම", "රූප අතර පූර්ණ හිස් අවකාශයක් තැබීම", "කිසිදු සම්බන්ධයක් නැති තනි රූප ලෙස තැබීම", "එක් රුවක් අනෙක් රුවට මඳක් ඉදිරියෙන් අතිච්ඡාදනය වීම අවකාශ ගැඹුර මවයි."),
        q("අනුරාධපුර යුගයේ චිත්‍ර කලාව අධ්‍යයනයේදී 'තීන්ත වර්ග පිළිබඳ විද්‍යාත්මක විශ්ලේෂණය' (Pigment Analysis) මගින් හෙළි වූයේ කුමක්ද?", "සියල්ල දේශීය හා ස්වාභාවික ඛනිජ හා ශාක වර්ණක බව", "යුරෝපීය කර්මාන්තශාලා තෙල් සායම් බව", "රසායනික ප්ලාස්ටික් ඩයි වර්ග බව", "ලෝහ උණු කර වීදුරු කළ බව", "රසායනික පරීක්ෂණවලින් ගුරුගල්, හුණු, කොළ පස් හා අඟුරු භාවිතය තහවුරු වී ඇත."),
        q("සීගිරි කුරුටු ගී ලිවීමට පැමිණි ඇතැම් රසිකයන් 'සිතුවම් කාන්තාවන් තමන් සමඟ කතා නොකරන්නේ මන්දැයි' ඇසීමෙන් පළ වන්නේ කුමක්ද?", "සිතුවම්වල පවතින අතිශය ජීවමාන සජීවී ස්වරූපය", "චිත්‍රවල මුහුණු අවලස්සන හා රෞද්‍ර බව", "චිත්‍ර ඉතා කුඩා බැවින් නොපෙනෙන බව", "කැටපත් පවුරේ ඉඩ නැති බව", "සිතුවම් කෙතරම් ජීවමානද යත් ඔවුන් සැබෑ මිනිසුන් මෙන් පෙනුණු බව කවියන් වර්ණනා කර ඇත."),
        q("අනුරාධපුර යුගයේ 'විහාර බිතුසිතුවම්' නිර්මාණය කිරීමේදී ශිල්පීන් අනුගමනය කළ සම්ප්‍රදායික ගුණාංගයක් නොවන්නේ කුමක්ද?", "සෑම රුවක්ම යුරෝපීය ඇඳුම් පැළඳුමින් සැරසීම", "රතු, කහ, සුදු, කොළ වර්ණ භාවිත කිරීම", "බදාම ස්තර දෙකක් හෝ තුනක් බිත්තියට යෙදීම", "සියුම් හා නම්‍යශීලී බාහිර රේඛාවක් ඇඳීම", "අනුරාධපුර සිතුවම් දේශීය හා පෙරදිග සම්භාව්‍ය සංස්කෘතිය මත පදනම් වූ අතර යුරෝපීය ඇඳුම් නැත."),
        q("අනුරාධපුරයේ 'ගල් ලෙන් විහාර' (උදා: ඉසුරුමුණිය, වෙස්සගිරිය) තුළ බිතුසිතුවම් ඇඳීමට සුදුසු පරිසරයක් සකස් වූයේ කෙසේද?", "කටාරම් කොටා ලෙන වියළිව තබා හුණු-මැටි බදාම ඇතිරීමෙන්", "ලෙන ඇතුළත වීදුරු බිත්ති බැඳීමෙන්", "ගල් බිත්ති මත තෙල් තීන්ත කෙළින්ම ගෑමෙන්", "මැටි වෙනුවට යකඩ තහඩු සවි කිරීමෙන්", "කටාරමෙන් ජලය පාලනය කළ පසු මැටි හා හුණු බදාම ගල් බිත්තියේ දීර්ඝ කාලයක් රැඳේ."),
        q("සීගිරියේ ලලනාවන්ගේ 'වළලු සහ පළඳනා' වර්ණ ගැන්වීමේදී දිලිසෙන රන් පැහැය හැඟවීමට ශිල්පියා යොදා ගත් උපක්‍රමය කුමක්ද?", "කහ ගුරුගල් හා හිරියල් මත සුදු හා රතු ආලෝක ඉස්මතු කිරීම් යෙදීම", "සැබෑ දියමන්ති ඔබ්බවා තැබීම", "ඇලුමිනියම් තහඩු කපා ඇලවීම", "ප්ලාස්ටික් පබළු ඇලවීම", "තද කහ, ලා කහ සහ සුදු තිත් හා රේඛා සංයෝජනයෙන් රන් ආභරණවල දිලිසෙන ගුණය මවා ඇත."),
        q("අනුරාධපුර යුගයේ චිත්‍ර කලාව හා පසුකාලීන පොළොන්නරු යුගයේ චිත්‍ර කලාව අතර ප්‍රධාන වෙනස කුමක්ද?", "අනුරාධපුරයේ නිදහස් ත්‍රිමාණ බව වැඩි අතර පොළොන්නරුවේ ආඛ්‍යාන කතා තීරු බහුල වීම", "අනුරාධපුරයේ තෙල් සායම්ද පොළොන්නරුවේ ජල සායම්ද භාවිත වීම", "පොළොන්නරුවේ සියලු සිතුවම් කළු-සුදු වීම", "අනුරාධපුරයේ කිසිදු බිතුසිතුවමක් නොතිබීම", "පොළොන්නරුවේ තිවංක පිළිමගෙයි ජාතක කතා ආඛ්‍යාන බහුල වූ අතර අනුරාධපුරය වඩා සම්භාව්‍ය විය."),
        q("සීගිරි බිතුසිතුවම්වල 'සමස්ත රූප සමූහය' දෙස බලන විට දැනෙන ප්‍රධාන සෞන්දර්ය හැඟීම කුමක්ද?", "ගාම්භීර සුන්දරත්වය, ශාන්ත බව හා අහසේ පාවෙන රිද්මය", "භයංකර යුද්ධය හා ලේ වැගිරීම", "වෙහෙසකර කෘෂිකාර්මික ශ්‍රමය", "කාර්මික යන්ත්‍ර සූත්‍රවල වේගය", "මෘදු වර්ණ, මල් ඉසීම හා ආකාශගාමී පාවීම මගින් සුන්දර ශාන්ත හැඟීමක් ජනිත වේ."),
        q("හිඳගල විහාරයේ බිතුසිතුවම් ආරක්ෂා වී ඇති ස්ථානය පිහිටි ලෙනෙහි පසුකාලීනව සිදු වූ වෙනස්කම කුමක්ද?", "විශාල සැතපෙන බුදු පිළිමයක් හා මහනුවර යුගයේ ඉදිකිරීම් එක් වීම", "ලෙන සම්පූර්ණයෙන් කඩා වේල්ලක් තැනීම", "පෘතුගීසි පල්ලියක් බවට පත් කිරීම", "ජලාශයකට සම්පූර්ණයෙන් යට වීම", "පැරණි ලෙන් වහලයේ අනුරාධපුර සිතුවම් ඉතිරිව ඇති අතර පහළින් සැතපෙන පිළිමයක් ඇත."),
        q("අනුරාධපුර යුගයේ බිතුසිතුවම්වල 'බදාම ස්තරවල හුණු පිළිස්සීම' සඳහා පුරාණ ශිල්පීන් භාවිත කළ ද්‍රව්‍යය කුමක්ද?", "මුහුදු බෙල්ලන් හා හුණුගල්", "කළුගල් සහ මුහුදු වැලි", "රතු මැටි සහ ලුණු කැට", "යකඩ ලෝපස් සහ දැව අඟුරු", "පිරිසිදු හුණු ලබා ගැනීමට මුහුදු බෙලිකටු හෝ හුණුගල් පුළුස්සා සිනිඳු කර ගෙන තිබේ."),
        q("සීගිරි බිතුසිතුවම්වල ඇඳ ඇති කාන්තා රූපවල 'ඉඟටිය' ප්‍රදේශය අධික ලෙස සිහින්ව ඇඳීමට හේතුව කුමක්ද?", "පෙරදිග සම්භාව්‍ය කාව්‍යමය රූප වර්ණනා රීතිය අනුගමනය කිරීම", "ශරීර විද්‍යාව නොදැන සිටීම", "රෙදි මැසීමේ මෝස්තරයක් පෙන්වීම", "කඩදාසියේ ඉඩ මදි වීම", "'මිටින් ගත හැකි සිහින් ඉඟ' වැනි සම්භාව්‍ය සෞන්දර්ය සංකල්ප මෙහිදී අනුගමනය කර ඇත."),
        q("අනුරාධපුර යුගයේ 'බිතුසිතුවම් ශිල්පියාගේ මෙවලම්' අතරට අයත් වන ප්‍රධාන උපකරණ මොනවාද?", "සත්ව ලොම් හා තෘණ පින්සල්, ගල් ඇඹරුම් තැටි හා පොල් කටු", "වානේ පැලට් පිහි සහ කැන්වස් රාමු", "එයාර් බ්‍රෂ් ස්ප්‍රේ යන්ත්‍ර", "මුද්‍රණ රෝලර් හා ප්ලාස්ටික් තැටි", "වැටකෙයියා හෝ සත්ව රෝමවලින් සැදූ දේශීය පින්සල් හා වර්ණ ඇඹරූ ගල් පුවරු භාවිත කෙරිණි."),
        q("අනුරාධපුර සම්භාව්‍ය බිතුසිතුවම් අධ්‍යයනය කිරීමෙන් මෙරට 'චිත්‍ර කලා ඉතිහාසය' ගැන තහවුරු වන වැදගත් කරුණ කුමක්ද?", "සීගිරිය හා ඒ ආශ්‍රිත කලාව දකුණු ආසියාවේ ඉහළම තලයක පැවති බව", "ලංකාවේ චිත්‍ර කලාව ඇරඹුණේ 19 වන සියවසේ බව", "සියලු චිත්‍ර ලන්දේසි ශිල්පීන් ඇඳි බව", "අනුරාධපුරයේදී මැටි බඳුන් පමණක් තැනූ බව", "ක්‍රි.ව. 5–9 සියවස්වලදී අනුරාධපුරය අද්විතීය චිත්‍ර කලා සම්ප්‍රදායකට හිමිකම් කී බව පැහැදිලිය."),
        q("සීගිරි සිතුවම් ලෙනෙහි පවතින කාන්තා රූප 22 අතරින් කී දෙනෙකු තනි රූප ලෙසත් කී දෙනෙකු යුගල ලෙසත් සංරක්ෂණය වී ඇත්ද?", "තනි රූප සහ යුගල රූප යන දෙවර්ගයම මිශ්‍රව දැකිය හැක", "සියල්ලම දසදෙනා බැගින් වූ කණ්ඩායම් වේ", "තනි රූප එකක්වත් නොමැත", "සියල්ලම සිරස් පේළියට ඇඳි තනි රූප වේ", "B ලෙනේ ඇති සුප්‍රකට රූප අතර තනිව මල් ඉසින ලලනාවන් මෙන්ම යුගල ලෙස සිටින රූපද වේ."),
        q("සීගිරි බිතුසිතුවම් හි 'වර්ණ සංයෝජනය' (Color Harmony) පිළිබඳව කලා විචාරකයන් දක්වන අදහස කුමක්ද?", "උණුසුම් රතු-කහ වර්ණ හා සිසිල් කොළ වර්ණ මනා සමතුලිතතාවකින් යෙදීම", "එකම තනි කළු පැහැය පමණක් යෙදීම", "වර්ණ විසි පහක් අපිළිවෙළට ගැසීම", "සුදු බදාමය පමණක් ඉතිරි කිරීම", "රතු, කහ සහ කොළ පෘථිවි වර්ණවල උණුසුම්-සිසිල් සමබරතාව සිතුවම්වලට චමත්කාරයක් ගෙන දෙයි."),
        q("හිඳගල විහාරයේ බිතුසිතුවම් කොටස් අතර බුදුරජාණන් වහන්සේගේ 'චීවරය' වර්ණ ගන්වා ඇති ආකාරය කෙබඳුද?", "රතු දුඹුරු හා කහ මිශ්‍ර පැහැයෙන් රැලි සෙවණැලි මතු කරමින්", "තද නිල් පැහැයෙන් රැලි රහිතව", "කොළ පැහැති කොටු රටාවකින්", "සුදු පැහැති පැතලි ආලේපයකින්", "සම්භාව්‍ය අනුරාධපුර ශෛලියට අනුව සිවුරේ රැලි මතු කරමින් රතු ගුරුගල් පැහැයෙන් ඇඳ ඇත."),
        q("සීගිරි සිතුවම්වල 'සමහර ලලනාවන්ගේ නළලේ හා හිසේ' ඇඳ ඇති සියුම් රේඛා සැරසිලි මගින් දැක්වෙන්නේ කුමක්ද?", "සිහින් කෙස් රොදවල් හා මුතු පටි ආභරණ", "තුවාල වූ සටන් කැළැල්", "නූතන ගණිත සංකේත", "ලෝහ යුද හිස්වැසුම්", "හිසකෙස් නළල දෙසට ගලා එන ආකාරය හා ආභරණ පටි ඉතා සියුම්ව ඇඳ ඇත."),
        q("අනුරාධපුර යුගයේ බිතුසිතුවම්වල 'මුහුදු බෙල්ලන්ගේ හුණු' හෙවත් සිප්පි හුණු භාවිතයෙන් බදාමයට ලැබුණු විශේෂ ගුණාංගය කුමක්ද?", "ඉතා සිනිඳු දීප්තිමත් සුදු මතුපිටක් හා දිගු කල් පැවැත්ම", "කළු රළු ගල් ස්වභාවයක්", "ඉක්මනින් දිය වී වැටෙන බවක්", "කොළ පැහැති දිලීර වර්ධනය වීමක්", "සිප්පි හුණු සියුම්ව අඹරා ගෑමෙන් දර්පණයක් වැනි සිනිඳු පසුබිමක් බිතුසිතුවමට ලැබේ."),
        q("සීගිරි කලාගාරයේ සිතුවම් නැරඹීමෙන් පසු කවියන් කැටපත් පවුරේ කුරුටු ගී ලිවීම 'ශ්‍රී ලාංකේය සෞන්දර්ය ඉතිහාසයට' වැදගත් වන්නේ ඇයි?", "ලොව පැරණිතම සංවිධානාත්මක කලා රසවින්දන හා විචාර සාක්ෂි සමූහයක් වීම", "පැරණි බදු ක්‍රමය ගැන ලියා තිබීම", "විදේශීය වෙළඳ නාමලේඛන වීම", "සිතුවම් ඇඳීමේ පිරිවැය ලේඛන වීම", "ප්‍රේක්ෂකයන්ගේ සජීවී කලා විචාරයන් කවියෙන් සටහන් වීම ලෝක කලා ඉතිහාසයේ විරල සිදුවීමකි."),
        q("අනුරාධපුර යුගයේ චිත්‍ර කලාව අවසන් වීමට හා පොළොන්නරු යුගය වෙත සංක්‍රමණය වීමට බලපෑ ඓතිහාසික සාධකය කුමක්ද?", "චෝල ආක්‍රමණ හා අගනුවර පොළොන්නරුවට මාරු වීම", "සීගිරිය භූමිකම්පාවකින් විනාශ වීම", "ලංකාවේ සියලු ගල් ලෙන් වැසී යාම", "චිත්‍ර ඇඳීම රජු විසින් තහනම් කිරීම", "11 වන සියවසේ රාජධානි මාරුවත් සමඟ දකුණු ඉන්දීය ආභාසය මිශ්‍ර වූ පොළොන්නරු කලා ශෛලිය බිහිවිය."),
        q("අනුරාධපුර යුගයේ සිතුවම් ශෛලියේ 'කැපී පෙනෙන රේඛා කුසලතාව' විස්තර කිරීමට වඩාත්ම සුදුසු යෙදුම කුමක්ද?", "ස්වභාවික රිද්මයානුකූල හා ආත්මවිශ්වාසයෙන් යුත් පින්සල් රේඛාව", "බියෙන් ගැහෙන කැඩුණු පැන්සල් ඉරි", "යන්ත්‍රයකින් ඇඳි කෙළින් කොටු රේඛා", "සියුම් විස්තර රහිත රළු අඟුරු සටහන්", "එකම පින්සල් පහරකින් සිරුරේ හැඩය හා ලාලිත්‍යය මැවීම අනුරාධපුර ශිල්පියාගේ විශේෂ හැකියාවයි."),
        q("සීගිරිය හා වෙස්සගිරිය වැනි ස්ථානවල බිතුසිතුවම් 'සංස්කෘතික සංචාරක කර්මාන්තයට' වැදගත් වන්නේ කෙසේද?", "ශ්‍රී ලංකාවේ අද්විතීය පෞරාණික කලා උරුමය ලොවට විදහා දැක්වීමෙන්", "සිතුවම් කපා විදේශිකයන්ට විකිණීමෙන්", "ලෙන් තුළ වාණිජ වෙළඳසැල් පවත්වාගෙන යාමෙන්", "පැරණි බදාම සූරා සිමෙන්ති සෑදීමෙන්", "ලෝක උරුම කලා කෘති ලෙස සීගිරි සිතුවම් දෙස් විදෙස් රසිකයන්ගේ ගෞරවයට පාත්‍ර වේ."),
        q("හිඳගල බිතුසිතුවම් සංරක්ෂණයේදී ඒවාට හානි වීමට ප්‍රධාන ලෙස බලපෑ ස්වභාවික හා මානව සාධක මොනවාද?", "තෙතමනය, දුම් වැදීම හා කාලගුණික ඛාදනය", "මුහුදු රළ වැදීම හා ලුණු සුළඟ", "හිම පතනය හා අයිස් මිදීම", "විදුලි දුම්රිය කම්පනය", "විහාරය තුළ දල්වන පහන් දුමාරය හා වර්ෂා තෙතමනය ලෙන් බිතුසිතුවම්වලට හානි ගෙන දෙයි."),
        q("අනුරාධපුර යුගයේ 'වියළි බදාම සිතුවම්' (Fresco Secco) ක්‍රමයේදී බදාමය වියළුණු පසු වර්ණ ආලේප කිරීමේ වාසිය කුමක්ද?", "සෙමෙන් හා ඉතා සියුම් විස්තර සහිතව සංකීර්ණ සෙවණැලි ඇඳීමට කාලය ලැබීම", "බදාමය වියළීමට පෙර පැයක් ඇතුළත ඉක්මනින් ඇඳ අවසන් කිරීමට සිදුවීම", "වර්ණ බදාමය ඇතුළට ගිලී සම්පූර්ණයෙන් අතුරුදන් වීම", "වර්ණවලට වතුර මිශ්‍ර කිරීමට අවශ්‍ය නොවීම", "තෙත බදාමයේ (Buon Fresco) මෙන් හදිසි කාල සීමාවක් නොමැති නිසා සියුම් අවසන් නිමාවක් කළ හැකි විය."),
        q("සීගිරි ලලනාවන්ගේ 'අත්වල දිගු ඇඟිලි' නිරූපණය කිරීමෙන් පෙනෙන සම්භාව්‍ය කලා ලක්ෂණය කුමක්ද?", "මහා පුරුෂ හා දිව්‍ය සෞන්දර්ය ලක්ෂණ අනුව සුන්දරත්වය ඉස්මතු කිරීම", "සැබෑ මිනිසුන්ට වඩා බියකරු රාක්ෂ ස්වරූපයක් දැක්වීම", "ශිල්පියාට ඇඟිලිවල දිග මැනීම වැරදීම", "වැඩ කරන ගොවි අත්වල රළු බව පෙන්වීම", "සුරතලය හා කලාත්මක නම්‍යශීලී බව දැක්වීමට දිගු සිහින් ඇඟිලි ඇඳීම සම්භාව්‍ය රීතියකි."),
        q("අනුරාධපුර යුගයේ බිතුසිතුවම් පිළිබඳව අධ්‍යයනයේදී 'වලාකුළු පසුබිම්' සහිත දේව රූප දක්නට ලැබෙන ස්ථාන මොනවාද?", "සීගිරිය, මිහින්තලේ ධාතු ගර්භය හා මහියංගණය", "ඇම්බැක්කේ, දෙගල්දොරුව හා මැදවල", "කැලණිය හා ගෝතමී විහාරය", "තොටගමුව හා මුල්කිරිගල", "සීගිරියේ මෙන්ම මිහින්තලේ කණ්ඨක චේතිය ආශ්‍රිත ධාතු ගර්භවලද වලාකුළු හා දේව රූප හමුවී ඇත."),
        q("සීගිරියේ ලෙන් බිතුසිතුවම්වල 'රන්වන්' හා 'අඳුරු' කාන්තාවන් අතර පවතින සමානකම කුමක්ද?", "දෙදෙනාම මෘදු ශාන්ත බව, සමාන කුණ්ඩලාභරණ හා සීගිරි රේඛා ලාලිත්‍යය දැරීම", "දෙදෙනාම තනි කළු සිලුවට් රූප වීම", "දෙදෙනාම අසිපත් අතින් ගෙන සිටීම", "දෙදෙනාම පිටුපස හරවා සිටීම", "සමේ පැහැය වෙනස් වුවද දෙවර්ගයේම මුහුණු හා රේඛා සම්භාව්‍ය සීගිරි ශෛලියෙන් යුක්තය."),
        q("අනුරාධපුර කලා යුගයේ චිත්‍ර ශිල්පීන් 'නිල් වර්ණය' සීගිරියේදී භාවිත නොකළද පසුව කුමන ස්ථානවල නිල් වර්ණය හමුවන්නේද?", "මහියංගණ ධාතු ගර්භය හා පසුකාලීන විහාර බිතුසිතුවම්වල", "දොරවක කන්ද ප්‍රාග් ඓතිහාසික කෙටුම්වල", "විලෙන්ඩෝෆ් වීනස් ප්‍රතිමාවේ", "සීගිරි කැටපත් පවුරේ අකුරුවල", "පසුකාලීන ධාතු ගර්භ සිතුවම් හා පොළොන්නරු-මහනුවර යුගවලදී නිල් පැහැයද යොදා ගැනිණි."),
        q("සීගිරි බිතුසිතුවම්වල ඇඳ ඇති සමහර කාන්තාවන්ගේ 'ඇස් කොන්වල රතු පැහැ' ස්පර්ශයක් යෙදීමෙන් සිදුවන්නේ කුමක්ද?", "දෑස්වලට සජීවී ජීවමය ප්‍රාණවත් බවක් ලැබීම", "කාන්තාවන් හඬමින් සිටින බව පෙන්වීම", "තීන්ත බිංදු අහම්බෙන් වැටීම", "රෝගී ස්වභාවයක් නිරූපණය කිරීම", "ඇස් කොන්වල සියුම් රතු රේඛාව ඉන්දීය හා හෙළ සම්භාව්‍ය සෞන්දර්ය වර්ණනාවේ ලක්ෂණයකි."),
        q("අනුරාධපුර යුගයේ 'බිතුසිතුවම් හා මූර්ති' අතර පවතින ශෛලිමය සබඳතාව කුමක්ද?", "දෙකෙහිම සංයමය, ශාන්තභාවය, ලාලිත්‍යය හා උසස් පරිමාණ ඥානය පැවතීම", "මූර්ති රෞද්‍ර වන අතර සිතුවම් විකට වීම", "දෙකෙහිම කිසිදු මානව රූපයක් නොතිබීම", "දෙකම විදේශීය කම්මල්වල නිපදවීම", "අනුරාධපුර සමාධි පිළිමයේ හා සීගිරි ලලනාවන්ගේ ශාන්ත රේඛා සංයමය එකම සංස්කෘතික ප්‍රකාශනයකි."),
        q("පුරාවිද්‍යා කැණීම්වලින් හමුවූ 'සීගිරි හා අනුරාධපුර බදාම කැබලි' අධ්‍යයනයේදී බිතුසිතුවම්වල වයස හා තාක්ෂණය දැනගන්නේ කෙසේද?", "බදාම ස්තර අන්වීක්ෂයෙන් හා රසායනිකව පරීක්ෂා කිරීමෙන්", "බදාම කැබැල්ලේ බර කිරා බැලීමෙන් පමණක්", "කැබලි ජලයේ දිය කර රස බැලීමෙන්", "හිරු එළියේ දවසක් තබා බැලීමෙන්", "විද්‍යාගාර පරීක්ෂණ මගින් බදාමයේ දහයියා, හුණු අනුපාත හා ඛනිජ වර්ණක නිවැරදිව හඳුනා ගැනේ."),
        q("අනුරාධපුර යුගයේ චිත්‍ර කලාව අධ්‍යයනය කරන සිසුවෙකුට 'සීගිරි කලාව' පිළිබඳව නිවැරදි සාරාංශය කුමක්ද?", "ක්‍රි.ව. 5 වන සියවසේ කාශ්‍යප රජ සමයේ බිහි වූ වියළි බදාම ත්‍රිමාණ සම්භාව්‍ය බිතුසිතුවම්ය", "ක්‍රි.ව. 18 වන සියවසේ කීර්ති ශ්‍රී රාජසිංහ රජු කළ ජාතක කතා සිතුවම්ය", "ප්‍රාග් ඓතිහාසික මිනිසුන් අඟුරෙන් ඇඳි සතුන්ගේ රූප පෙළකි", "පොළොන්නරු යුගයේ චෝල ආක්‍රමණිකයන් තැනූ ලෝකඩ ප්‍රතිමා පෙළකි", "සීගිරි බිතුසිතුවම් යනු අනුරාධපුර යුගයේ සම්භාව්‍ය හෙළ සිතුවම් කලාවේ මුදුන්මල්කඩයි.")
    )
}
